import pyomo.environ as pyo

DATA = {
    "nodes": [1, 2, 3, 4],
    "source": 1,
    "sink": 4,
    "arcs": [(1, 2), (1, 3), (2, 3), (2, 4), (3, 4)],
    "capacity": {
        (1, 2): 8,
        (1, 3): 7,
        (2, 3): 2,
        (2, 4): 4,
        (3, 4): 12,
    },
    "intermediate_nodes": [2, 3],
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.NODES = pyo.Set(initialize=d["nodes"])
    model.ARCS = pyo.Set(initialize=d["arcs"], dimen=2)
    model.INTERMEDIATE = pyo.Set(initialize=d["intermediate_nodes"])

    # flow[i,j]: amount of flow on arc (i,j), bounded by arc capacity
    def flow_bounds(m, i, j):
        return (0, d["capacity"][(i, j)])

    model.flow = pyo.Var(
        model.ARCS,
        domain=pyo.NonNegativeReals,
        bounds=flow_bounds,
    )

    # Objective: maximize total flow leaving the source
    def obj_rule(m):
        return sum(
            m.flow[i, j] for (i, j) in d["arcs"] if i == d["source"]
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Flow conservation at each intermediate node: inflow == outflow
    def conservation_rule(m, n):
        inflow = sum(
            m.flow[i, j] for (i, j) in d["arcs"] if j == n
        )
        outflow = sum(
            m.flow[i, j] for (i, j) in d["arcs"] if i == n
        )
        return inflow - outflow == 0

    model.conservation = pyo.Constraint(
        model.INTERMEDIATE, rule=conservation_rule
    )

    return model


