import pyomo.environ as pyo

DATA = {
    "nodes": [1, 2, 3, 4],
    "arcs": [
        (1, 2, 8),
        (1, 3, 7),
        (2, 3, 2),
        (2, 4, 4),
        (3, 4, 12),
    ],
    "interior_nodes": [2, 3],
    "source": 1,
    "sink": 4,
}


def build_model(data=None):
    d = data if data is not None else DATA

    arc_list = [(a[0], a[1]) for a in d["arcs"]]
    cap = {(a[0], a[1]): a[2] for a in d["arcs"]}

    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=d["nodes"])
    model.A = pyo.Set(initialize=arc_list, dimen=2)
    model.I = pyo.Set(initialize=d["interior_nodes"])

    def cap_rule(m, i, j):
        return cap[(i, j)]

    model.cap = pyo.Param(model.A, initialize=cap_rule, mutable=False)

    # x[a] = flow on arc a, bounded by capacity
    model.x = pyo.Var(model.A, within=pyo.NonNegativeReals)

    def x_bound_rule(m, i, j):
        return (0, m.cap[i, j])

    # Apply per-arc upper bound through an explicit bound constraint
    def x_upper_rule(m, i, j):
        return m.x[i, j] <= m.cap[i, j]
    model.x_upper = pyo.Constraint(model.A, rule=x_upper_rule)

    # Outflow from node n
    def out_expr(m, n):
        return sum(m.x[i, j] for (i, j) in arc_list if i == n)

    # Inflow to node n
    def in_expr(m, n):
        return sum(m.x[i, j] for (i, j) in arc_list if j == n)

    # Conservation at interior nodes (inflow = outflow)
    def conserve_rule(m, n):
        return in_expr(m, n) - out_expr(m, n) == 0
    model.conserve = pyo.Constraint(model.I, rule=conserve_rule)

    # Objective: maximize net outflow from source
    model.obj = pyo.Objective(
        expr=out_expr(model, d["source"]) - in_expr(model, d["source"]),
        sense=pyo.maximize,
    )

    return model


